"""Source-bound interval measurement for a designated bus stop.

A duration is an observed quantity. This module never decides a legal verdict.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_bound(root: Path, ref: dict, expected_kind: str) -> dict:
    rel = ref.get("path")
    if not isinstance(rel, str) or rel.startswith("/") or ".." in Path(rel).parts:
        raise ValueError("unsafe source path")
    target = (root / rel).resolve()
    if not target.is_relative_to(root.resolve()) or not target.is_file():
        raise ValueError("missing source: " + str(rel))
    if sha(target) != ref.get("sha256"):
        raise ValueError("changed source: " + str(rel))
    value = json.loads(target.read_text())
    if value.get("kind") != expected_kind:
        raise ValueError("wrong source kind: " + expected_kind)
    return value


def measure(root: Path, refs: dict, *, expected_frames: int = 900, diagnostic: bool = False) -> dict:
    kinds = {
        "site": "reviewed_bus_stop_site",
        "designation": "bus_stop_duration_designation",
        "identity": "bus_operator_identity",
        "activity": "bus_activity_review",
        "native": "native_bus_frame_ledger",
    }
    packets = {key: read_bound(root, refs[key], kind) for key, kind in kinds.items()}
    if any(p.get("source_class") == "synthetic_diagnostic" for p in packets.values()) and not diagnostic:
        raise ValueError("synthetic diagnostic source cannot establish original measurement")
    site, designation, identity, activity, native = (packets[k] for k in kinds)
    if site.get("cell_id") != "C393262" or site.get("layout") != "residence_district" or site.get("stop_kind") != "bus_stop":
        raise ValueError("wrong site or stop kind")
    if not site.get("reviewer") or not site.get("designation_source_sha256") or not site.get("boundary_source_sha256"):
        raise ValueError("missing independently reviewed stop source")
    if designation.get("stop_id") != site.get("stop_id") or designation.get("authority") != "City Traffic Engineer":
        raise ValueError("designation does not bind this stop and authority")
    d = designation.get("applicable_duration_s")
    if not isinstance(d, (int, float)) or d <= 0 or not designation.get("conditions_reviewed"):
        raise ValueError("missing actual applicable designated duration or conditions")
    if designation.get("source_sha256") != site.get("designation_source_sha256"):
        raise ValueError("site designation source mismatch")
    if identity.get("bus_id") != native.get("bus_id") or identity.get("tour_bus") is not False or not identity.get("covered_operator"):
        raise ValueError("covered non-tour bus/operator identity unproved")
    rows = native.get("frames")
    if not isinstance(rows, list) or len(rows) != expected_frames:
        raise ValueError("incomplete Native frame ledger")
    for i, row in enumerate(rows):
        if row.get("frame") != i or abs(row.get("time_s", -1) - i / 20) > 0.00001:
            raise ValueError("Native frame/time join failed")
        if row.get("bus_id") != identity["bus_id"]:
            raise ValueError("bus identity changed in frame ledger")
        if not isinstance(row.get("inside_stop_boundary"), bool):
            raise ValueError("missing body-to-stop boundary observation")
    events = activity.get("events")
    if not isinstance(events, list) or len(events) < 2 or not activity.get("independent_reviewer"):
        raise ValueError("missing independently reviewed activity transitions")
    conduct = activity.get("conduct")
    if conduct not in ("stand", "park"):
        raise ValueError("standing/parking conduct unresolved")
    start, end = events[0], events[-1]
    if start.get("event") != "start" or end.get("event") != "end":
        raise ValueError("complete activity start/end not observed")
    begin = start.get("frame"); finish = end.get("frame")
    if not isinstance(begin, int) or not isinstance(finish, int) or begin < 0 or finish >= expected_frames or finish <= begin:
        raise ValueError("activity interval outside capture")
    if any(not rows[i]["inside_stop_boundary"] for i in range(begin, finish + 1)):
        raise ValueError("bus body left designated stop during measured interval")
    if any(e.get("event") in ("load", "unload", "merchandise") for e in events):
        raise ValueError("activity changed; independent interval segmentation required")
    observed = (finish - begin) / 20
    return {
        "case_measurement": "bus_stop_standing_or_parking_duration",
        "site_stop_id": site["stop_id"],
        "conduct": conduct,
        "observed_duration_s": observed,
        "applicable_designated_duration_s": float(d),
        "difference_s": observed - float(d),
        "interval_frames": [begin, finish],
        "source_refs": refs,
        "diagnostic_only": bool(diagnostic),
        "legal_verdict": None,
    }

"""Source-gated CARLA bus-stop duration acquisition with owned actors.

The requested D-relative hold is an engineering target. Original activity timing
and location are measured from Native frames and independently reviewed later.
"""
from __future__ import annotations

import copy
import hashlib
import json
import math
import queue
from pathlib import Path

VIEWS = ('overview', 'approach', 'reference_corner', 'driver_reference')
SIZES = {'overview': (1920, 1080), 'approach': (1280, 720),
         'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


def sha(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def finite(value, name: str) -> float:
    if not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError('invalid ' + name)
    return float(value)


def pose(value: dict) -> dict:
    if not isinstance(value, dict):
        raise ValueError('reviewed Native transform missing')
    for key in ('x', 'y', 'z', 'yaw'):
        finite(value.get(key), key)
    return value


def read_site(path: Path, expected_sha256: str) -> dict:
    path = Path(path)
    if sha(path) != expected_sha256:
        raise ValueError('reviewed bus-stop site SHA256 differs')
    site = json.loads(path.read_text())
    if site.get('source_kind') != 'original_independent_site_review' or site.get('cell_id') != 'C393262':
        raise ValueError('original independent C393262 site review required')
    if site.get('layout') != 'residence_district' or site.get('stop_kind') != 'bus_stop':
        raise ValueError('reviewed residential bus stop differs')
    for key in ('reviewer', 'map_sha256', 'stop_id', 'stop_boundary_source_sha256',
                'designation_source_sha256', 'operator_source_sha256'):
        if not site.get(key):
            raise ValueError('missing reviewed bus-stop source: ' + key)
    designation = site.get('designation')
    if not isinstance(designation, dict) or designation.get('authority') != 'City Traffic Engineer' or \
            designation.get('stop_id') != site['stop_id'] or not designation.get('conditions_reviewed') or \
            designation.get('source_sha256') != site['designation_source_sha256']:
        raise ValueError('actual stop-specific designation unproved')
    boundary = site.get('stop_polygon_xy_m')
    if not isinstance(boundary, list) or len(boundary) < 4 or any(not isinstance(point, list) or len(point) != 2 for point in boundary):
        raise ValueError('reviewed bus stop boundary polygon required')
    for point in boundary:
        finite(point[0], 'stop boundary x');finite(point[1], 'stop boundary y')
    duration = finite(designation.get('applicable_duration_s'), 'applicable designated duration')
    if duration <= 2 or duration > 30:
        raise ValueError('actual designated duration does not fit 45 s complete-interval profile')
    identity = site.get('bus_identity')
    if not isinstance(identity, dict) or identity.get('tour_bus') is not False or not identity.get('covered_operator') or not identity.get('bus_id'):
        raise ValueError('covered non-tour bus/operator identity unproved')
    scene = site.get('native_scene')
    if not isinstance(scene, dict) or not str(scene.get('bus_blueprint_id', '')).startswith('vehicle.'):
        raise ValueError('reviewed Native bus blueprint required')
    for key in ('approach_pose', 'stop_pose', 'exit_pose'):
        pose(scene.get(key))
    cameras = scene.get('camera_mounts')
    if not isinstance(cameras, dict) or set(cameras) != set(VIEWS):
        raise ValueError('four reviewed camera mounts required')
    for spec in cameras.values():
        pose(spec.get('transform'))
        if spec.get('attach_to') not in ('bus', 'world'):
            raise ValueError('reviewed camera parent differs')
        if not 0 < finite(spec.get('fov_deg'), 'camera fov') < 180:
            raise ValueError('reviewed camera fov differs')
    return site


def inside_polygon(point, polygon) -> bool:
    x,y=point;inside=False
    for i in range(len(polygon)):
        x1,y1=polygon[i-1];x2,y2=polygon[i]
        if ((y1>y)!=(y2>y)) and x<(x2-x1)*(y-y1)/(y2-y1)+x1:
            inside=not inside
    return inside


def steer_toward(transform, target: dict) -> float:
    loc=transform.location
    heading=math.degrees(math.atan2(target['y']-loc.y,target['x']-loc.x))
    delta=(heading-transform.rotation.yaw+180)%360-180
    return max(-1.0,min(1.0,delta/45.0))


def requested_hold(site: dict, relation: str) -> float:
    duration = float(site['designation']['applicable_duration_s'])
    if relation not in ('below', 'at', 'above'):
        raise ValueError('unknown duration relation')
    target = duration + {'below': -2.0, 'at': 0.0, 'above': 2.0}[relation]
    if target <= 0 or target > 32:
        raise ValueError('duration target outside complete capture profile')
    return target


class NativeBusOperator:
    def __init__(self, world, carla, site: dict):
        self.world, self.carla, self.site = world, carla, site
        self.owned = []
        self.bus = None
        self.cameras = {}

    def transform(self, value: dict):
        value = pose(value)
        return self.carla.Transform(self.carla.Location(x=value['x'], y=value['y'], z=value['z']),
                                    self.carla.Rotation(yaw=value['yaw'], pitch=value.get('pitch', 0), roll=value.get('roll', 0)))

    def setup(self):
        if sha_bytes(self.world.get_map().to_opendrive().encode('utf-8')) != self.site['map_sha256']:
            raise ValueError('reviewed OpenDRIVE differs from Native world')
        scene = self.site['native_scene']
        try:
            blueprint = self.world.get_blueprint_library().find(scene['bus_blueprint_id'])
            self.bus = self.world.spawn_actor(blueprint, self.transform(scene['approach_pose']))
            if self.bus is None:
                raise ValueError('Native bus actor spawn failed')
            self.owned.append(self.bus)
            for name in VIEWS:
                spec = scene['camera_mounts'][name]
                blueprint = self.world.get_blueprint_library().find('sensor.camera.rgb')
                width, height = SIZES[name]
                blueprint.set_attribute('image_size_x', str(width))
                blueprint.set_attribute('image_size_y', str(height))
                blueprint.set_attribute('fov', str(spec['fov_deg']))
                kwargs = {'attach_to': self.bus} if spec['attach_to'] == 'bus' else {}
                camera = self.world.spawn_actor(blueprint, self.transform(spec['transform']), **kwargs)
                if camera is None:
                    raise ValueError('Native bus camera spawn failed: ' + name)
                self.owned.append(camera)
                self.cameras[name] = camera
            return {'bus_actor_id': self.bus.id, 'camera_actor_ids': {name: camera.id for name, camera in self.cameras.items()}}
        except BaseException:
            self.close()
            raise

    def close(self):
        errors = []
        for actor in reversed(self.owned):
            try:
                if hasattr(actor, 'stop'):
                    actor.stop()
                actor.destroy()
            except BaseException as error:
                errors.append(error)
        self.owned.clear(); self.cameras.clear(); self.bus = None
        if errors:
            raise ValueError('Native bus ownership cleanup failed') from errors[0]

    def capture(self, output: Path, conduct: str, relation: str) -> dict:
        if self.bus is None or set(self.cameras) != set(VIEWS):
            raise ValueError('bus and four cameras must be constructed')
        if conduct not in ('stand', 'park'):
            raise ValueError('unknown standing or parking conduct')
        hold = requested_hold(self.site, relation)
        output = Path(output)
        if output.exists():
            raise ValueError('retain prior Native bus attempt')
        output.mkdir(parents=True)
        previous = copy.deepcopy(self.world.get_settings())
        settings = copy.deepcopy(previous)
        settings.synchronous_mode = True; settings.fixed_delta_seconds = .05
        self.world.apply_settings(settings)
        inbox = {name: queue.Queue() for name in VIEWS}
        rows = []
        state = 'approach'; hold_start = None; hold_end = None
        stop = self.site['native_scene']['stop_pose']; exit_pose = self.site['native_scene']['exit_pose']
        try:
            for name, sensor in self.cameras.items():
                sensor.listen(lambda image, q=inbox[name]: q.put(image))
            for index in range(900):
                transform = self.bus.get_transform(); loc = transform.location
                velocity = self.bus.get_velocity()
                speed = math.sqrt(velocity.x**2 + velocity.y**2 + velocity.z**2)
                distance_to_stop = math.hypot(loc.x-stop['x'], loc.y-stop['y'])
                distance_to_exit = math.hypot(loc.x-exit_pose['x'], loc.y-exit_pose['y'])
                if state == 'approach' and distance_to_stop < 2.5:
                    state = 'settle'
                if state == 'settle' and speed < .1:
                    state = 'hold'; hold_start = index
                if state == 'hold' and (index-hold_start)/20 >= hold:
                    state = 'depart'; hold_end = index
                if state == 'depart' and distance_to_exit < 2.5:
                    state = 'clear'
                if state in ('approach', 'depart'):
                    target=stop if state == 'approach' else exit_pose
                    control = self.carla.VehicleControl(throttle=.28, steer=steer_toward(transform,target), brake=0, hand_brake=False)
                else:
                    control = self.carla.VehicleControl(throttle=0, brake=1,
                                                        hand_brake=(state == 'hold' and conduct == 'park'))
                self.bus.apply_control(control)
                frame = self.world.tick()
                cameras = {}
                for name in VIEWS:
                    image = inbox[name].get(timeout=30)
                    if image.frame != frame:
                        raise ValueError('Native bus camera/world frame mismatch')
                    folder = output / name;folder.mkdir(exist_ok=True)
                    path = folder / f'{index:04d}.png';image.save_to_disk(str(path))
                    cameras[name] = {'path': str(path.relative_to(output)), 'sha256': sha(path), 'native_frame': frame}
                transform = self.bus.get_transform();loc = transform.location
                velocity = self.bus.get_velocity()
                speed = math.sqrt(velocity.x**2 + velocity.y**2 + velocity.z**2)
                box = self.bus.bounding_box
                corners=[]
                for sx,sy in ((-1,-1),(1,-1),(1,1),(-1,1)):
                    vertex=transform.transform(box.location+self.carla.Location(x=sx*box.extent.x,y=sy*box.extent.y,z=0))
                    corners.append([finite(vertex.x,'body x'),finite(vertex.y,'body y')])
                in_stop=all(inside_polygon(point,self.site['stop_polygon_xy_m']) for point in corners)
                rows.append({'frame': index,'time_s':index/20,'original_frame':frame,'bus_id':self.site['bus_identity']['bus_id'],'native_actor_id':self.bus.id,
                             'bus_center_xy_m':[finite(loc.x,'bus x'),finite(loc.y,'bus y')],
                             'bus_footprint_xy_m':corners,'bus_speed_mps':speed,
                             'controller_state':state,'inside_stop_boundary':in_stop,
                             'cameras':cameras})
            if hold_start is None or hold_end is None or state not in ('depart','clear'):
                raise ValueError('Native bus did not complete requested stopped interval and departure')
            ledger = {'kind':'native_bus_frame_ledger','source_class':'original_native_capture',
                      'bus_id':self.site['bus_identity']['bus_id'],'native_actor_id':self.bus.id,'frames':rows,'controller_hold_frames':[hold_start,hold_end],
                      'physical_acceptance':False,'legal_verdict':None}
            path=output/'native_frames.json';path.write_text(json.dumps(ledger,indent=2)+'\n')
            return {'native_frames_sha256':sha(path),'frame_count':900,'hold_target_s':hold,
                    'controller_hold_frames':[hold_start,hold_end],'physical_acceptance':False}
        finally:
            for sensor in self.cameras.values():
                sensor.stop()
            self.world.apply_settings(previous)


def sha_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def capture(adapter, site_path: Path, case_id: str, destination: Path) -> dict:
    """The adapter owns a dedicated CARLA world connection, not a server lifecycle."""
    site_path=Path(site_path)
    expected=site_path.with_suffix(site_path.suffix+'.sha256')
    if not expected.is_file():
        raise ValueError('independent reviewed site SHA256 sidecar required')
    site=read_site(site_path,expected.read_text().strip())
    relation=case_id.split('__')[-1].split('_')[-1]
    conduct=case_id.split('__')[-1].split('_')[0]
    operator=NativeBusOperator(adapter.world,adapter.carla,site)
    try:
        setup=operator.setup()
        result=operator.capture(destination,conduct,relation)
        result.update(setup)
        result['case_id']=case_id
        result['reviewed_site_sha256']=sha(site_path)
        return result
    finally:
        operator.close()

"""Saved source finalizer for actual bus-stop designation versus full interval."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from bus_duration import measure

ASSIGNMENT = 'testing__C393262__LVMC-11-60-030-A5__bus_driver'
VIEWS = ('overview', 'approach', 'reference_corner', 'driver_reference')
SOURCES = ('duration-source-packet.json', 'site.json', 'designation.json',
           'identity.json', 'activity.json', 'native.json')


def source(attempt: Path, name: str) -> Path:
    path = attempt / name
    if not path.is_file() or not path.resolve().is_relative_to(attempt.resolve()):
        raise ValueError('Missing required source: ' + name)
    return path


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def trace_row(index: int, row: dict) -> dict:
    x, y = row.get('bus_center_xy_m', [0.0, 0.0])
    speed = float(row.get('bus_speed_mps', 0.0))
    return {'frame': row.get('original_frame', index), 'time_s': row['time_s'],
            'position': {'x': x, 'y': y, 'z': 0.0}, 'position_m': [x,y,0.0],
            'heading_deg': 0.0, 'speed_mps': speed, 'speed_mph': speed / .44704,
            'velocity_mps': [speed,0.0,0.0], 'road_id': 10,
            'control': {'throttle': 0.0, 'brake': 1.0,
                        'hand_brake': False, 'steer': 0.0}}


def measure_bus_identity(observation: dict) -> dict:
    return {'covered_non_tour_bus_operator': True,
            'observed_conduct': observation['conduct'],
            'source_sha256': observation['source_refs']['identity']['sha256']}


def measure_stop_designation(observation: dict) -> dict:
    return {'stop_id': observation['site_stop_id'],
            'source_sha256': observation['source_refs']['site']['sha256']}


def measure_designated_limit(observation: dict) -> dict:
    return {'applicable_designated_duration_s': observation['applicable_designated_duration_s'],
            'source_sha256': observation['source_refs']['designation']['sha256']}


def measure_activity_interval(observation: dict) -> dict:
    return {'conduct': observation['conduct'], 'interval_frames': observation['interval_frames'],
            'observed_duration_s': observation['observed_duration_s']}


def measure_duration_relation(observation: dict) -> dict:
    return {'difference_s': observation['difference_s'],
            'observed_duration_s': observation['observed_duration_s'],
            'applicable_designated_duration_s': observation['applicable_designated_duration_s'],
            'legal_verdict': None}


def relation_matches(relation: str, difference_s: float) -> bool:
    if relation == 'below':
        return difference_s < -0.05
    if relation == 'at':
        return abs(difference_s) <= 0.05
    if relation == 'above':
        return difference_s > 0.05
    raise ValueError('unknown selected duration relation')


def write_saved_outputs(attempt: Path, packet: dict, observation: dict) -> None:
    construction = json.loads(source(attempt, 'construction.json').read_text())
    description = construction['recording_description']
    native = json.loads(source(attempt, 'native.json').read_text())
    frames = native['frames']
    if len(frames) != 900:
        raise ValueError('full 900-frame original Native bus history required')
    video_refs = [name + '.mkv' for name in VIEWS]
    video_hashes = {name: sha(source(attempt, name)) for name in video_refs}
    traces = [trace_row(i, row) for i,row in enumerate(frames)]
    trace_text = ''.join(json.dumps(row, sort_keys=True) + '\n' for row in traces)
    trace = attempt / 'trace.jsonl'
    if trace.exists():
        if trace.read_text() != trace_text:
            raise ValueError('original bus trace differs from source-bound Native frames')
    else:
        trace.write_text(trace_text)
    mapping = [{'video_frame': i, 'carla_frame': row.get('original_frame', i),
                'native_frame': row.get('original_frame', i), 'time_s': row['time_s']}
               for i,row in enumerate(frames)]
    map_text = ''.join(json.dumps(row, sort_keys=True) + '\n' for row in mapping)
    map_path = attempt / 'video_frames.jsonl'
    if map_path.exists():
        if map_path.read_text() != map_text:
            raise ValueError('original camera frame map differs from bus Native frames')
    else:
        map_path.write_text(map_text)
    channels = attempt / 'channels'
    channels.mkdir(exist_ok=False)
    observations = {
        'bus_stopped_interval': lambda row,i: {'conduct': observation['conduct'],
                                                  'inside': observation['interval_frames'][0] <= i <= observation['interval_frames'][1]},
        'applicable_designated_duration': lambda row,i: observation['applicable_designated_duration_s'],
        'body_inside_stop': lambda row,i: row['inside_stop_boundary'],
        'four_camera_frame_identity': lambda row,i: {'original_frame': row.get('original_frame',i),
                                                        'video_frame': i, 'video_sha256': video_hashes},
    }
    evidence = []
    for channel in description['channels']:
        name = channel['name']
        target = channels / (name + '.jsonl')
        target.write_text(''.join(json.dumps({'time_s': row['time_s'], 'value': observations[name](row,i)}, sort_keys=True) + '\n'
                                  for i,row in enumerate(frames)))
        evidence.append({'name':name, 'unit':channel['unit'], 'reference':str(target.relative_to(attempt))})
    context = channels / 'source_context.json'
    context.write_text(json.dumps({'reviewed_site_and_designation': {'site_sha256': observation['source_refs']['site']['sha256'], 'designation_sha256': observation['source_refs']['designation']['sha256']}, 'bus_operator_and_activity': {'identity_sha256': observation['source_refs']['identity']['sha256'], 'activity_sha256': observation['source_refs']['activity']['sha256']}}, indent=2, sort_keys=True) + '\n')
    evidence.extend({'name':item['name'], 'unit':item['unit'], 'reference':str(context.relative_to(attempt))}
                    for item in description['context_inputs'])
    result = {'case_id': packet['case_id'],
              'measured_values': {'bus_stop_duration_s': observation['observed_duration_s'],
                                  'designated_duration_s': observation['applicable_designated_duration_s'],
                                  'difference_s': observation['difference_s'], 'conduct': observation['conduct']},
              'target_checks': [{'target':'complete stopped interval relative to reviewed D',
                                 'requested': packet['duration_relation'],
                                 'measured': observation['difference_s'],
                                 'method':'source-bound independent activity transition and 900 Native frames',
                                 'tolerance': 0.05, 'matched': relation_matches(packet['duration_relation'], observation['difference_s']),
                                 'physical_cause_confirmed': False,
                                 'cause_evidence': {key:ref['sha256'] for key,ref in observation['source_refs'].items()}}],
              'setup_confirmed': False, 'behavior_attempted': False, 'maneuver_completed': False,
              'termination_reason':'source measurement only; physical and legal acceptance pending',
              'physical_failure_flags': {'original_capture_unreviewed': True},
              'trace_reference':'trace.jsonl','video_references':video_refs,
              'video_frame_map_reference':'video_frames.jsonl',
              'recording_description': description, 'recording_evidence': evidence,
              'realized_observables': {}, 'diagnostic_fixture':packet.get('diagnostic_fixture') is True,
              'provenance_kind':'synthetic_fixture' if packet.get('diagnostic_fixture') else 'original_native'}
    (attempt/'result.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n')


def analyze(attempt: Path, output: Path) -> dict:
    attempt=attempt.resolve()
    for name in SOURCES:
        source(attempt,name)
    packet=json.loads(source(attempt,'duration-source-packet.json').read_text())
    case_id=packet.get('case_id')
    if not isinstance(case_id,str) or not case_id.startswith(ASSIGNMENT+'__'):
        raise ValueError('exact bus duration case identity required')
    config=json.loads(source(attempt,'config.json').read_text())
    if config['selected_case_id']!=case_id:
        raise ValueError('saved bus case differs from selected construction')
    observation=measure(attempt,packet['source_refs'],diagnostic=packet.get('diagnostic_fixture') is True)
    if observation['conduct']!=config['case']['conduct']:
        raise ValueError('measured bus conduct differs from selected case')
    methods=[('bus_identity',measure_bus_identity),('stop_designation',measure_stop_designation),
             ('designated_limit',measure_designated_limit),('activity_interval',measure_activity_interval),
             ('duration_relation',measure_duration_relation)]
    hashes={name:sha(source(attempt,name)) for name in SOURCES}
    report={'format':'worker-bus-duration-source-analysis','case_id':case_id,
            'measurements':{key:{'method':method.__name__,'value':method(observation),'sources':hashes}
                            for key,method in methods},
            'observation':observation,'legal_verdict':None,
            'scope':'source-bound saved duration; original physical and legal acceptance separate'}
    if output.name!='analysis-report.json':
        raise ValueError('analysis output must be analysis-report.json')
    output.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
    write_saved_outputs(attempt,packet,observation)
    return report


